package android.os;import java.util.*;public class Bundle{private final Map<String,Object> data=new HashMap<>();public void putBoolean(String k,boolean v){data.put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(data.get(k));}public void putInt(String k,int v){data.put(k,v);}public int getInt(String k){return (int)data.get(k);}public void putLong(String k,long v){data.put(k,v);}public void putString(String k,String v){data.put(k,v);}public String getString(String k){return (String)data.get(k);}public void putParcelable(String k,Object v){data.put(k,v);}public <T>T getParcelable(String k,Class<T> c){return c.cast(data.get(k));}}
